// ── Daten aus vorherigen Nodes holen ──────────────────────────────────────
const rev         = $('GET REVENUE1').first().json;
const cnt         = $('GET ORDERS COUNT1').first().json;
const orderDetails = $('GET ORDER DETAILS1').all();

const umsatzB2C   = rev.Umsatz_B2C   ?? '0.00';
const umsatzB2B   = rev.Umsatz_B2B   ?? '0.00';
const anzahlB2C   = cnt.Anzahl_B2C   ?? 0;
const anzahlB2B   = cnt.Anzahl_B2B   ?? 0;

// ── Produkttabelle aufbauen ────────────────────────────────────────────────
let tableRows = '';
for (const item of orderDetails) {
  const d = item.json;
  // Zeile nur rendern wenn Werte > 0 vorhanden
  const hasB2C = (d.Menge_B2C > 0 || d.Umsatz_B2C > 0);
  const hasB2B = (d.Menge_B2B > 0 || d.Umsatz_B2B > 0);
  if (!hasB2C && !hasB2B) continue;

  tableRows += `
  <tr bgcolor="#ffffff">
    <td>${d.Artikelnummer}</td>
    <td>${d.Artikelname}</td>
    <td style="text-align:right;">${hasB2C ? d.Menge_B2C : '-'}</td>
    <td style="text-align:right;">${hasB2C ? d.Umsatz_B2C + '&euro;' : '-'}</td>
    <td style="text-align:right;">${hasB2B ? d.Menge_B2B : '-'}</td>
    <td style="text-align:right;">${hasB2B ? d.Umsatz_B2B + '&euro;' : '-'}</td>
  </tr>`;
}

const productTable = `
<table cellspacing="0" cellpadding="5" border="1"
       style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:12px;">
  <tr bgcolor="#1a1a1a" style="color:white;">
    <td colspan="2"></td>
    <td colspan="2" style="text-align:center;background:#2e6da4;"><b>B2C (LEAF / CINNA)</b></td>
    <td colspan="2" style="text-align:center;background:#276a3a;"><b>B2B (JTL-Wawi)</b></td>
  </tr>
  <tr bgcolor="#333333" style="color:white;">
    <td><b>Artikelnummer</b></td>
    <td><b>Artikelname</b></td>
    <td style="background:#3a7ec4;"><b>Menge</b></td>
    <td style="background:#3a7ec4;"><b>Umsatz</b></td>
    <td style="background:#328a4a;"><b>Menge</b></td>
    <td style="background:#328a4a;"><b>Umsatz</b></td>
  </tr>
  ${tableRows}
</table>`;

// ── Datumsformatierung (de-DE) ─────────────────────────────────────────────
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

const formatted = yesterday.toLocaleDateString('de-DE', {
  day: '2-digit', month: '2-digit', year: 'numeric'
});

// ── E-Mail-Body ────────────────────────────────────────────────────────────
const emailHtml = `
<html>
<meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
<body style="font-family:Arial,sans-serif;font-size:14px;color:#222;">
  Hallo liebes BOTANICA-Team,<br><br>
  folgend erhaltet ihr den neuen Bestell-Bericht:<br><br>

  <table cellspacing="0" cellpadding="6" border="0"
         style="font-family:Arial,sans-serif;font-size:14px;">
    <tr>
      <td></td>
      <td style="background:#2e6da4;color:white;padding:4px 12px;"><b>B2C</b><br><small>LEAF &amp; CINNA</small></td>
      <td style="background:#276a3a;color:white;padding:4px 12px;"><b>B2B</b><br><small>JTL-Wawi</small></td>
    </tr>
    <tr>
      <td><b>Gesamtumsatz</b></td>
      <td style="text-align:right;">${umsatzB2C} EUR</td>
      <td style="text-align:right;">${umsatzB2B} EUR</td>
    </tr>
    <tr>
      <td><b>Bestellungen</b></td>
      <td style="text-align:right;">${anzahlB2C}</td>
      <td style="text-align:right;">${anzahlB2B}</td>
    </tr>
  </table>

  <br><b>PRODUKTSTATISTIK:</b><br><br>
  ${productTable}
</body>
</html>`;

return [{
  json: {
    subject:     `BOTANICA | Sales Report vom ${formatted}`,
    emailHtml,
    umsatzB2C,
    umsatzB2B,
    anzahlB2C,
    anzahlB2B
  }
}];

